"""Hand-authored release 0.7 content; run once against 0.6. No random variants."""
import json,re,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
cat=json.loads((ROOT/'content/catalog.yaml').read_text())
assert not any(c['id']=='encor' for c in cat['courses'])
cat['courses'].append(dict(id='encor',title='CCNP ENCOR 350-401',exam='350-401',blueprint_version='1.2',modules=[]))
existing={}
all_new=[]
def start(key,title,obj,urls,extend=False):
 global meta,tasks,cards
 meta=(key,title,obj,urls,extend);tasks=[];cards=[]
def base(title,prompt,explain,hint):
 key,title_m,obj,urls,ext=meta;n=len(tasks)+1
 tid=f'encor.{key}.'+('ext.' if ext else '')+f'{n:02}'
 d=([2,3,3] if ext else [1,2,3])[(n-1)//6]
 common=dict(id=tid,revision=1,title=title,skills=[f'{key}.'+re.sub(r'[^a-z0-9]+','-',title.lower()).strip('-')],sources=[dict(title='Dokumentacja Cisco — '+title_m,url=u) for u in urls])
 return dict(common,blueprint_refs=[dict(exam='350-401',version='1.2',objective=obj)],difficulty=d,prompt_md=prompt,hints=[hint or explain],explanation_md=explain,card_id=tid+'.theory')
def card(t,example):
 cards.append({k:t[k] for k in ['revision','title','skills','sources']}|dict(id=t['card_id'],front_md=t['title'],back_md=t['explanation_md'],example=example));tasks.append(t)
def q(title,prompt,answer,wrong,explain,hint=''):
 t=base(title,prompt,explain,hint);n=len(tasks);pos=(n*3+n//6)%4
 opts=[]
 for w in wrong:
  text,reason=w.split('|',1);opts.append(dict(text_md=text,feedback_md=reason))
 opts.insert(pos,dict(text_md=answer,feedback_md=explain));assert len(opts)==4
 for i,o in enumerate(opts):o['id']='ABCD'[i]
 t.update(type='single_choice',options=opts,correct_option_id='ABCD'[pos]);card(t,answer)
def c(title,prompt,template,values,explain,hint=''):
 t=base(title,prompt,explain,hint);blanks=[];example=template
 for i,v in enumerate(values):
  if isinstance(v,str):a=[v];typ='command'
  else:a,typ=v
  blanks.append(dict(id=f'b{i}',label=f'Luka {i+1}',answer_type=typ,accepted=a,width=min(56,max(6,len(a[0])+2)),common_errors={}))
  example=example.replace('{{b'+str(i)+'}}',a[0])
 t.update(type='cli_fill_blank',platform='Cisco IOS / IOS XE; zgodnie z założeniami zadania',template=template,blanks=blanks);card(t,example)
def end():
 key,title,obj,urls,ext=meta;assert len(tasks)==18,(key,len(tasks))
 module=existing.get('encor.'+key) if ext else dict(id='encor.'+key,title=title,description='Od pojęć do analizy i praktycznych scenariuszy.',stages=[])
 if not ext:
  assert module['id'] not in existing
  cat['courses'][-1]['modules'].append(module)
 start_order=len(module['stages'])
 for i in range(3):
  order=start_order+i+1;sid=f'encor.{key}.stage-{order}';path=f'content/encor/{key}/stage-{order}.yaml'
  p=ROOT/path;assert not p.exists(),path;p.parent.mkdir(parents=True,exist_ok=True)
  p.write_text(json.dumps(dict(schema_version=3,id=sid,revision=1,cards=cards[i*6:i*6+6],tasks=tasks[i*6:i*6+6]),ensure_ascii=False,indent=2)+'\n')
  module['stages'].append(dict(id=sid,title=(['Rozszerzenie — zależności','Rozszerzenie — konfiguracja','Rozszerzenie — diagnostyka'] if ext else ['Podstawy','Zastosowanie','Scenariusze'])[i],description='Sześć zadań z teorią i wyjaśnieniem odpowiedzi.',difficulty=tasks[i*6]['difficulty'],order=order,pack_url='/'+path.replace('.yaml','.json'),pack_revision=1,task_count=6,pass_percent=80,requires=[] if order==1 else [f'encor.{key}.stage-{order-1}']))
 all_new.extend(tasks)


def Q(title,prompt,options,explain):
 q(title,prompt,options[0],[x+'|'+explain for x in options[1:]],explain,'Przeanalizuj warunki scenariusza; odpowiedź dotyczy wyłącznie podanych założeń.')
def C(title,prompt,template,values,explain):
 c(title,prompt,template,values,explain,'Zwróć uwagę na tryb konfiguracji i parametry wymienione w poleceniu.')
def save():
 assert len(all_new)==180,len(all_new)
 cat['revision']+=1
 (ROOT/'content/catalog.yaml').write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n')
 print('Added',len(all_new),'ENCOR tasks')
BGP='https://www.cisco.com/c/en/us/support/docs/ip/border-gateway-protocol-bgp/13753-25.html'
OSPF='https://www.cisco.com/c/en/us/support/docs/ip/open-shortest-path-first-ospf/9237-9.html'
TUN='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ip-routing/b-ip-routing/m_ir-impl-tun-xe.html'
VRF='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ip-routing/b-ip-routing/m_ir-vrf-tunnels.html'
SLA='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ip-addressing/b-ip-addressing/m_sla_icmp_echo.html'
SPAN='https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst9600/software/release/17-3/configuration_guide/nmgmt/b_173_nmgmt_9600_cg/configuring_span_and_rspan.html'
BP='https://learningcontent.cisco.com/documents/marketing/exam-topics/350-401-ENCORE-v1.2.pdf'
start('ebgp','eBGP — sąsiedztwo i wybór trasy','3.2.c',[BGP])
Q('Granica AS','R1 należy do AS 65001, R2 do AS 65002. Jaki typ sesji BGP zestawiają?', ['eBGP','iBGP','OSPF inter-area','EIGRP internal'],'eBGP łączy różne systemy autonomiczne; iBGP działa wewnątrz jednego AS.')
Q('Transport BGP','ACL przepuszcza ping, ale blokuje transport sesji BGP. Który ruch musi dopuścić między peerami?', ['TCP 179','UDP 179','IP protocol 89','UDP 520'],'BGP używa TCP z portem serwera 179. Osiągalność ICMP nie dowodzi dostępności TCP.')
C('Zdalny system autonomiczny','R1 w AS 65001 ma bezpośredniego sąsiada 192.0.2.2 w AS 65002. Uzupełnij numer zdalnego AS.','router bgp 65001\n neighbor 192.0.2.2 remote-as {{b0}}',['65002'],'remote-as wskazuje AS sąsiada, a nie lokalnego routera.')
Q('Stan Established','W show ip bgp summary kolumna State/PfxRcd zawiera liczbę 12. Co to oznacza?', ['Sesja Established i 12 odebranych prefiksów','Sesja Idle od 12 sekund','Numer zdalnego AS wynosi 12','Dokładnie 12 błędów TCP'],'Liczba prefiksów zastępuje nazwę stanu, gdy sesja BGP jest zestawiona.')
C('Dokładna maska network','W RIB istnieje 10.20.0.0/16. Rozgłoś dokładnie ten prefiks przez BGP.','router bgp 65001\n network 10.20.0.0 mask {{b0}}',['255.255.0.0'],'Polecenie network wymaga odpowiadającej mu trasy o dokładnie zgodnym prefiksie i masce w RIB.')
Q('BGP to nie odkrywanie','Interfejsy dwóch routerów są up/up i mają adresy w jednym /30. Dlaczego samo to nie tworzy sesji BGP?', ['Sąsiada należy jawnie skonfigurować','BGP wymaga wyboru DR','BGP zawsze wymaga area 0','BGP działa tylko na loopbackach'],'Typowa sesja eBGP wymaga konfiguracji neighbor oraz zgodnych AS i osiągalności transportu.')
Q('Active nie znaczy gotowe','State/PfxRcd pokazuje Active zamiast liczby. Jaki wniosek jest uzasadniony?', ['Sesja nie osiągnęła Established','Router już wymienia prefiksy','Najlepsza ścieżka jest aktywna','Zawsze występuje błędna maska network'],'Active jest stanem zestawiania sesji. Sprawdź TCP, osiągalność i konfigurację peera; sam stan nie wskazuje jednej przyczyny.')
Q('Waga lokalna','Dwie poprawne ścieżki do tego samego /24 mają weight 200 i 100. Pozostałe ustawienia są domyślne. Która wygrywa?', ['Weight 200','Weight 100','Zawsze krótszy AS_PATH','Zawsze mniejszy MED'],'Cisco preferuje większy weight przed local preference i długością AS_PATH. Weight ma znaczenie lokalne.')
C('Pełna deklaracja peera','R1 działa w AS 65100; bezpośredni R2 pod 198.51.100.2 należy do AS 65200. Uzupełnij oba numery.','router bgp {{b0}}\n neighbor 198.51.100.2 remote-as {{b1}}',['65100','65200'],'Numer w router bgp jest lokalny; remote-as należy do drugiej strony sesji.')
Q('Długość AS_PATH','Dwie ścieżki mają równy weight i local preference; żadna nie jest lokalnie wygenerowana. AS_PATH to 65200 65300 oraz 65400. Co jest preferowane?', ['Ścieżka przez 65400','Ścieżka przez 65200 65300','Zawsze mniejszy pierwszy ASN','Obie zawsze trafiają do ECMP'],'Przy równych wcześniejszych kryteriach krótszy AS_PATH jest preferowany. Sama równość nie gwarantuje multipath.')
C('Dwa konkretne prefiksy','RIB zawiera 172.20.4.0/24 i 172.20.8.0/23. Rozgłoś je w AS 65001, uzupełniając maski.','router bgp 65001\n network 172.20.4.0 mask {{b0}}\n network 172.20.8.0 mask {{b1}}',['255.255.255.0','255.255.254.0'],'BGP network nie przyjmuje wildcard. /24 odpowiada 255.255.255.0, a /23 — 255.255.254.0.')
Q('Zasięg weight','Na R1 zwiększono weight dla tras od ISP-A. Czy R2 w tym samym AS otrzyma ten weight przez iBGP?', ['Nie, weight nie jest rozgłaszany','Tak, jako obowiązkowy atrybut','Tak, tylko przez eBGP','Tak, w polu MED'],'Weight jest lokalnym parametrem Cisco. Do polityki wspólnej dla AS stosuje się m.in. local preference.')
Q('Brak dokładnej trasy','RIB ma tylko 10.44.0.0/16. Skonfigurowano network 10.44.1.0 mask 255.255.255.0. Dlaczego /24 nie jest originowane?', ['Brakuje dokładnej trasy 10.44.1.0/24 w RIB','BGP zabrania adresów prywatnych','Network automatycznie dzieli /16 na /24','Maska musi być wildcard'],'Trasa nadrzędna /16 nie spełnia warunku dokładnego dopasowania wpisu network /24.')
Q('Local preference przed AS_PATH','Obie trasy mają weight 0 i nie są lokalne. A: local-pref 200, AS_PATH długości 4. B: local-pref 100, AS_PATH długości 1. Co wybierze router?', ['A','B','Losowo A lub B','Zawsze obie'],'Większy local preference wygrywa przed porównaniem długości AS_PATH.')
C('Pierwszy peering z ISP','R1: AS 64520, R2: 203.0.113.2 w AS 64530. W RIB jest 10.60.0.0/16. Uzupełnij lokalny AS, zdalny AS i maskę ogłoszenia.','router bgp {{b0}}\n neighbor 203.0.113.2 remote-as {{b1}}\n network 10.60.0.0 mask {{b2}}',['64520','64530','255.255.0.0'],'Bezpośredni eBGP wymaga poprawnego remote-as. Ogłoszenie network opiera się na istniejącym dokładnym prefiksie.')
Q('Nieosiągalny next hop','Ścieżka ma najwyższy local-pref, lecz jej next hop jest nieosiągalny. Druga ścieżka jest poprawna. Co należy uwzględnić?', ['Nieosiągalny next hop dyskwalifikuje ścieżkę','Local-pref zawsze wymusza instalację','BGP naprawi next hop przez ARP w całym Internecie','MED zastąpi brak osiągalności'],'Algorytm wybiera spośród poprawnych ścieżek. Wyższy atrybut nie naprawia nieosiągalnego next hop.')
C('Dwa łącza eBGP','W AS 65010 ustaw lokalny weight 150 dla peera 192.0.2.2 w AS 65020 i weight 50 dla peera 198.51.100.2 w AS 65030. Uzupełnij zdalne AS i wyższy weight.','router bgp 65010\n neighbor 192.0.2.2 remote-as {{b0}}\n neighbor 192.0.2.2 weight {{b1}}\n neighbor 198.51.100.2 remote-as {{b2}}\n neighbor 198.51.100.2 weight 50',['65020','150','65030'],'Dla wspólnych poprawnych prefiksów wyższy weight preferuje pierwszego peera wyłącznie na tym routerze.')
Q('MED z jednego AS','Dwie ścieżki od tego samego sąsiedniego AS są równe we wcześniejszych kryteriach. MED wynosi 20 i 80. Jaki jest wybór przy domyślnym porównaniu MED?', ['MED 20','MED 80','Większy local router-id niezależnie od MED','MED jest zawsze ignorowany'],'Przy porównywalnych ścieżkach z tego samego sąsiedniego AS mniejszy MED jest preferowany.')
end()
start('ospf-multi','OSPF — obszary, agregacja i OSPFv3','3.2.b',[OSPF])
Q('Router graniczny obszaru','R1 ma interfejs w area 0 i interfejs w normalnym area 10. Jaką rolę pełni?', ['ABR','Wyłącznie ASBR','Route reflector','Designated forwarder VXLAN'],'ABR łączy obszary OSPF. ASBR wprowadza trasy zewnętrzne przez redystrybucję.')
Q('Backbone','Który obszar stanowi szkielet standardowej hierarchii OSPF?', ['Area 0','Area 1','Obszar o największym ID','Każdy obszar z DR'],'Ruch między obszarami opiera się na backbone area 0; normalne obszary dołączają do niego przez ABR.')
C('Przypisanie obszaru','W procesie OSPF 10 przypisz Gi0/1 do normalnego area 20.','interface GigabitEthernet0/1\n ip ospf 10 area {{b0}}',['20'],'Przypisanie interfejsowe bezpośrednio wskazuje proces i obszar OSPF.')
Q('Trasa między obszarami','W show ip route widzisz O IA 10.2.0.0/16. Jak odczytać IA?', ['Trasa OSPF z innego obszaru','Trasa zewnętrzna typu 2','Bezpośrednio podłączona sieć','Trasa statyczna do Internetu'],'O IA oznacza inter-area. Zwykłe O oznacza trasę intra-area.')
C('Dwa routery bez wyboru DR','Na ethernetowym łączu z dokładnie dwoma routerami ustaw po obu stronach typ OSPF point-to-point. Uzupełnij lokalne polecenie.','interface GigabitEthernet0/0\n ip ospf network {{b0}}',['point-to-point'],'Typ point-to-point nie wybiera DR/BDR. Należy zachować spójny typ sieci między końcami.')
Q('LSA typu 3','Który router generuje podsumowania między obszarami OSPFv2 w postaci LSA typu 3?', ['ABR','Każdy host końcowy','Tylko BDR','Wyłącznie router iBGP'],'ABR opisuje osiągalność sieci innych obszarów za pomocą LSA typu 3; nie przenosi całej bazy typu 1 bez zmian.')
Q('Dwa procesy lokalne','Na wspólnym łączu R1 używa procesu OSPF 10, a R2 procesu 99. Pozostałe parametry są zgodne. Czy różne process ID blokują sąsiedztwo OSPFv2?', ['Nie, ID procesu ma znaczenie lokalne','Tak, zawsze','Tylko w area 0','Tylko przy typie point-to-point'],'Process ID nie musi zgadzać się między routerami. Obszar i wymagane parametry sąsiedztwa muszą być zgodne.')
Q('Agregacja na ABR','Area 10 ma sieci 10.10.0.0/24 do 10.10.3.0/24. Jaka jest najmniejsza pojedyncza agregacja obejmująca dokładnie te cztery sieci?', ['10.10.0.0/22','10.10.0.0/23','10.10.0.0/21','10.10.1.0/22'],'Cztery kolejne /24 od granicy trzeciego oktetu 0 mieszczą się dokładnie w /22.')
C('Konfiguracja area range','Na ABR procesu 10 agreguj sieci z area 10 do 10.10.0.0/22, ogłaszając podsumowanie innym obszarom.','router ospf 10\n area {{b0}} range 10.10.0.0 {{b1}}',['10','255.255.252.0'],'area range wskazuje obszar źródłowy agregowanych sieci i maskę podsieci, nie wildcard.')
Q('Pasywny LAN','LAN z użytkownikami jest objęty OSPF i ma passive-interface. Co jest prawdą?', ['Sieć może być ogłaszana, ale interfejs nie zestawia sąsiedztwa','Sieć zawsze znika z OSPF','Interfejs administracyjnie się wyłącza','Router wysyła Hello, ale ignoruje tylko LSA'],'Passive-interface zatrzymuje Hello i sąsiedztwo na LAN; nie usuwa automatycznie ogłaszanego prefiksu.')
C('Zezwól tylko na tranzyt','W procesie 10 ustaw domyślnie wszystkie interfejsy jako passive, lecz aktywuj Hello na Gi0/0.','router ospf 10\n passive-interface {{b0}}\n no passive-interface {{b1}}',['default','GigabitEthernet0/0'],'Domyślna pasywność ogranicza sąsiedztwa do jawnie dopuszczonych łączy tranzytowych.')
Q('OSPFv3 i router ID','Router działa wyłącznie z IPv6. Jaki format ma router ID OSPFv3?', ['32-bitowa wartość zapisana jak IPv4','128-bitowy adres IPv6','48-bitowy MAC','Numer AS w notacji asdot'],'Router ID OSPFv3 pozostaje 32-bitowy. Zapis jak IPv4 nie wymaga uruchomienia IPv4 na interfejsach.')
Q('Diagnoza 2-WAY','W sieci broadcast dwa routery DROTHER widzą się w stanie 2-WAY; oba mają FULL z DR i BDR. Jak to ocenić?', ['To prawidłowe zachowanie','To zawsze awaria MTU','Należy ustawić wszystkim priorytet 255','OSPF nie obsługuje trzech routerów w LAN'],'DROTHER nie tworzą pełnej adjacencji między sobą w sieci broadcast. FULL jest wymagane z DR/BDR.')
Q('Filtr prefix-list na ABR','ABR używa area 20 filter-list prefix BLOCK in. W jakim kierunku działa ten filtr LSA typu 3?', ['Na ogłoszenia wchodzące do area 20','Na pakiety użytkowników wychodzące z Gi0/0','Na wszystkie LSA typu 1 wewnątrz area 20','Na sesje TCP do routera'],'Kierunek in jest względem obszaru. Filtr dotyczy międzyobszarowych prefiksów typu 3, nie filtrowania pakietów danych.')
C('Dwa normalne obszary','Proces 10: Gi0/0 jest w area 0, Gi0/1 w area 30. Ustaw na Gi0/0 typ point-to-point.','interface GigabitEthernet0/0\n ip ospf 10 area {{b0}}\n ip ospf network {{b1}}\ninterface GigabitEthernet0/1\n ip ospf 10 area {{b2}}',['0','point-to-point','30'],'Router z interfejsami w backbone i innym obszarze pełni rolę ABR; typ sieci konfiguruje się per interfejs.')
Q('Stan EXSTART','Sąsiedzi na łączu OSPF pozostają w EXSTART/EXCHANGE. Obszar i Hello są zgodne, MTU wynosi 1500 i 1400. Co sprawdzić w pierwszej kolejności?', ['Niezgodność MTU i negocjację DBD','Numer lokalnego procesu','Wartość TCP MSS dla sesji BGP','DNS routerów'],'Niezgodność MTU jest typową przyczyną problemów z wymianą DBD. Należy usunąć przyczynę, a nie zakładać błąd process ID.')
C('OSPFv3 w klasycznej składni','Użyj klasycznej składni IOS XE ipv6 router ospf. Proces 20, router-id 1.1.1.1; Gi0/0 ma już IPv6 i należy do area 0.','ipv6 unicast-routing\nipv6 router ospf {{b0}}\n router-id {{b1}}\ninterface GigabitEthernet0/0\n ipv6 ospf 20 area {{b2}}',['20','1.1.1.1','0'],'Klasyczna składnia OSPFv3 włącza protokół na interfejsie poleceniem ipv6 ospf; nie używa IPv4 network wildcard.')
Q('Agregat i dziura','ABR ogłasza 10.10.0.0/22, ale jedna z czterech sieci /24 jest niedostępna, a pozostałe nadal istnieją. Jaki jest skutek agregacji?', ['Agregat może pozostać mimo niedostępności części zakresu','Agregat zawsze znika w całości','OSPF tworzy brakującą podsieć','Cały area 0 przechodzi w passive'],'Agregacja ukrywa szczegóły. Istniejące składowe mogą utrzymywać podsumowanie obejmujące nieosiągalny fragment.')
end()
start('vrf','VRF — oddzielne tablice routingu','2.2.a',[VRF])
Q('Izolacja klientów','Dwaj klienci używają 10.0.0.0/24 na tym samym routerze. Co pozwala utrzymać oddzielne tablice routingu?', ['VRF','Sam opis interfejsu','Samo zwiększenie MTU','Sam hostname'],'VRF tworzy niezależny kontekst routingu. Nakładające się adresy mogą istnieć w różnych VRF.')
Q('VRF-lite','Co odróżnia zastosowanie VRF-lite od wymogu uruchomienia MPLS w rdzeniu?', ['VRF-lite może działać bez MPLS','VRF-lite zawsze wymaga LDP','VRF-lite jest tylko VLAN-em','VRF-lite usuwa potrzebę routingu'],'Oddzielne tablice VRF nie wymagają same w sobie MPLS. VRF-lite może korzystać z oddzielnych interfejsów L3.')
C('Nowy kontekst','Utwórz VRF o dokładnej nazwie BLUE w składni vrf definition.','vrf definition {{b0}}\n address-family ipv4\n exit-address-family',[(['BLUE'],'identifier')],'Nazwa VRF identyfikuje kontekst. address-family ipv4 włącza rodzinę adresową tej definicji.')
Q('Brak domyślnego przecieku','BLUE i RED mają kompletne trasy we własnych tablicach. Bez route leaking czy trasy automatycznie stają się wspólne?', ['Nie','Tak, jeśli numery VLAN są kolejne','Tak, po ping do 127.0.0.1','Tak, jeśli mają ten sam RD'],'Izolacja jest podstawą VRF. Komunikacja między kontekstami wymaga jawnego mechanizmu i polityki.')
C('Przypisanie interfejsu','Istnieje VRF BLUE. Przypisz do niego Gi0/1 przed nadaniem adresu IP.','interface GigabitEthernet0/1\n vrf forwarding {{b0}}\n ip address 10.1.0.1 255.255.255.0',[(['BLUE'],'identifier')],'vrf forwarding umieszcza interfejs w tablicy VRF. Konfigurację IP należy wykonywać po przypisaniu VRF.')
Q('Odczyt tablicy BLUE','Które polecenie pokazuje tablicę IPv4 konkretnego VRF BLUE?', ['show ip route vrf BLUE','show vlan BLUE','show ip arp global-only','show spanning-tree BLUE'],'show ip route bez wskazania VRF dotyczy tablicy globalnej, a nie wszystkich kontekstów.')
Q('Adres znika','Po dodaniu vrf forwarding BLUE na skonfigurowanym interfejsie IOS XE usuwa jego adres IPv4. Co należy zrobić?', ['Ponownie nadać adres w odpowiednim VRF','Zawsze usunąć całą konfigurację routera','Zamienić maskę na wildcard','Włączyć BGP dla wszystkich VRF'],'Zmiana przynależności VRF może usuwać adresację interfejsu. Stąd kolejność: VRF, następnie adres.')
Q('Ping z właściwego miejsca','Globalny ping 10.1.0.2 nie działa, choć BLUE ma poprawną trasę. Jaki test odpowiada temu kontekstowi?', ['ping vrf BLUE 10.1.0.2','ping global BLUE','ping vlan BLUE 10.1.0.2','ping 10.1.0.2 ttl BLUE'],'Test powinien używać VRF, w którym znajdują się źródło i trasa. Globalna RIB może celowo nie mieć tej sieci.')
C('Trasa statyczna BLUE','W BLUE skonfiguruj 172.20.0.0/16 przez bezpośrednio osiągalny next hop 10.1.0.2.','ip route vrf {{b0}} 172.20.0.0 {{b1}} 10.1.0.2',[(['BLUE'],'identifier'),'255.255.0.0'],'Parametr vrf kieruje wpis do oddzielnej RIB. Next hop musi być rozwiązywalny w odpowiednim kontekście.')
Q('Globalny default nie pomaga','VRF RED ma tylko trasę connected. Router posiada globalny default route. Dlaczego host RED nadal nie ma wyjścia?', ['RED nie dziedziczy automatycznie globalnej trasy domyślnej','Default musi mieć maskę /32','Każdy VRF używa wyłącznie IPv6','Nazwa RED wyłącza routing'],'Tablice są oddzielne. Trasa globalna nie jest automatycznie trasą VRF.')
C('Adres w RED','Istnieje VRF RED. Gi0/2 ma otrzymać 192.0.2.1/30. Uzupełnij nazwę i maskę.','interface GigabitEthernet0/2\n vrf forwarding {{b0}}\n ip address 192.0.2.1 {{b1}}',[(['RED'],'identifier'),'255.255.255.252'],'Adres przypisany po vrf forwarding tworzy trasę connected w RED, nie w globalnej RIB.')
Q('RD a polityka','Czy samo nadanie różnego route distinguisher automatycznie definiuje import i eksport tras VPN między VRF?', ['Nie; RD odróżnia prefiksy, a politykę określają m.in. route targets','Tak; RD jest listą ACL','Tak; RD automatycznie zestawia GRE','Nie; RD to numer VLAN'],'RD i RT pełnią różne funkcje. RD rozróżnia prefiksy VPN, a RT uczestniczy w polityce importu/eksportu MP-BGP.')
Q('Nakładające się connected','Gi0/1 w BLUE ma 10.0.0.1/24, Gi0/2 w RED ma 10.0.0.1/24. Co jest poprawną interpretacją?', ['Adresacja może współistnieć w oddzielnych VRF','Router musi połączyć obie sieci w jeden broadcast domain','RED zawsze wygrywa przez kolejność alfabetyczną','Każdy pakiet jest kopiowany do obu VRF'],'Kontekst interfejsu wybiera tablicę. Nakładające się prefiksy nie powodują automatycznego połączenia klientów.')
Q('Diagnoza asymetrii','R1 ma w BLUE trasę do zdalnego hosta. Ping z poprawnym źródłem nie wraca. Co trzeba jeszcze sprawdzić?', ['Trasę powrotną do źródła i polityki po drodze','Wyłącznie nazwę hostname','Tylko globalne OSPF process ID','Wyłącznie kolejność definicji VRF'],'Poprawna trasa w jedną stronę nie dowodzi dwukierunkowej łączności. Zweryfikuj powrót i filtrowanie.')
C('Pełna konfiguracja klienta','Utwórz BLUE dla IPv4, dodaj Gi0/1 10.8.0.1/24 i default przez 10.8.0.2. Uzupełnij trzy brakujące elementy.','vrf definition BLUE\n address-family {{b0}}\n exit-address-family\ninterface GigabitEthernet0/1\n vrf forwarding BLUE\n ip address 10.8.0.1 {{b1}}\nexit\nip route vrf BLUE 0.0.0.0 0.0.0.0 {{b2}}',['ipv4','255.255.255.0','10.8.0.2'],'Rodzina adresowa, adres interfejsu i trasa muszą należeć do spójnego kontekstu klienta.')
Q('Trasa w złej RIB','Administrator wpisał ip route 10.90.0.0 255.255.0.0 10.8.0.2 bez vrf BLUE. Jaki jest pierwszy problem?', ['Wpis trafił do globalnej konfiguracji routingu','IOS automatycznie wybrał BLUE po next hop','Maska /16 jest nielegalna w VRF','Polecenie zawsze tworzy trasę we wszystkich VRF'],'Bez parametru vrf wpis nie jest konfigurowany w BLUE, niezależnie od intencji administratora.')
C('Oddzielne trasy dwóch klientów','BLUE: 10.40.0.0/16 przez 192.0.2.2. RED: ten sam prefiks przez 198.51.100.2. Oba next hopy są osiągalne w swoich VRF.','ip route vrf {{b0}} 10.40.0.0 255.255.0.0 {{b1}}\nip route vrf {{b2}} 10.40.0.0 255.255.0.0 198.51.100.2',[(['BLUE'],'identifier'),'192.0.2.2',(['RED'],'identifier')],'Ten sam prefiks może prowadzić do różnych next hopów, ponieważ każdy klient ma własną tablicę.')
Q('Trasa connected we właściwym VRF','W globalnym show ip route nie widać 10.8.0.0/24. Gi0/1 jest up/up w BLUE. Jaki jest najlepszy następny odczyt?', ['show ip route vrf BLUE 10.8.0.0','show spanning-tree root','show ip bgp summary bez sprawdzania VRF','show interfaces trunk jako jedyny test'],'Brak wpisu w globalnej RIB jest oczekiwany dla interfejsu należącego do VRF. Odczytaj odpowiednią tablicę.')
end()
start('gre','GRE — tunele i zależność od underlay','2.2.b',[TUN])
Q('Cel GRE','Dwie wyspy routingu mają komunikować się przez sieć pośrednią IP. Co zapewnia zwykły GRE?', ['Enkapsulację pakietów w tunelu','Domyślne szyfrowanie AES','Automatyczne uwierzytelnienie certyfikatem','Gwarantowane pasmo'],'GRE przenosi pakiet wewnętrzny w pakiecie zewnętrznym. Sam nie zapewnia poufności.')
Q('Numer protokołu','ACL między końcami ma dopuścić zwykły GRE przez IPv4. Który numer protokołu IP jest istotny?', ['47','TCP 47','UDP 500','89'],'GRE używa numeru protokołu IP 47; nie jest to port TCP lub UDP. UDP 500 wiąże się z IKE.')
C('Cel tunelu','R1 ma outer IP 192.0.2.1, R2 198.51.100.2. Uzupełnij destination na R1.','interface Tunnel0\n tunnel source 192.0.2.1\n tunnel destination {{b0}}',['198.51.100.2'],'Destination wskazuje osiągalny adres zewnętrzny drugiego końca, nie adres jego interfejsu Tunnel.')
Q('Underlay','Jaki warunek musi spełniać routing fizycznej sieci dla utworzenia działającego GRE?', ['Musi istnieć osiągalność zewnętrznego celu tunelu','Musi znać wszystkie prefiksy klientów','Musi uruchamiać ten sam proces OSPF co overlay','Musi być jednym VLAN-em'],'Underlay dostarcza pakiety do outer destination. Nie musi znać sieci przenoszonych wewnątrz tunelu.')
C('Jawny tryb GRE IPv4','Ustaw jawnie klasyczny punkt-punkt GRE przez IPv4.','interface Tunnel0\n tunnel mode {{b0}}',['gre ip'],'tunnel mode gre ip określa klasyczny GRE przez IPv4. Tryb i obsługę funkcji należy sprawdzić dla platformy.')
Q('Adres wewnętrzny','Na Tunnel0 jest 10.255.0.1/30, source 192.0.2.1. Który adres jest częścią sieci overlay?', ['10.255.0.1','192.0.2.1','Oba zawsze są adresami underlay','Żaden — GRE nie ma overlay'],'Adres interfejsu Tunnel należy do logicznego łącza; tunnel source wskazuje zewnętrzny punkt enkapsulacji.')
Q('GRE a IPsec','Wymagana jest poufność ruchu przenoszonego przez GRE w publicznej sieci. Co jest potrzebne?', ['Dodatkowa ochrona, np. IPsec','Tylko większy tunnel key','Tylko adres prywatny na Tunnel0','Wyłącznie zmiana numeru interfejsu'],'GRE nie szyfruje danych. IPsec może chronić transport tunelu, zależnie od przyjętego projektu.')
Q('Minimalny narzut','Załóż zewnętrzny IPv4 bez opcji (20 B) i bazowy GRE bez key/checksum (4 B). Ile bajtów dodaje enkapsulacja?', ['24','4','20','48'],'Dla tych jawnych założeń narzut wynosi 20 + 4 = 24 B. Opcje GRE i IPsec zwiększają narzut.')
C('Adresacja i destination','Na R1 ustaw Tunnel10 10.255.10.1/30 i outer destination 203.0.113.2. Source jest już poprawny.','interface Tunnel10\n ip address 10.255.10.1 {{b0}}\n tunnel destination {{b1}}',['255.255.255.252','203.0.113.2'],'Maska dotyczy wewnętrznego łącza /30, natomiast destination — zewnętrznego końca tunelu.')
Q('Rekurencja','Najlepsza trasa do outer destination GRE wskazuje sam Tunnel0. Jaki problem powstaje?', ['Rekurencyjna zależność tunelu od samego siebie','Automatyczne zwiększenie bezpieczeństwa','Poprawna wymagana konfiguracja każdego GRE','Wyłącznie konflikt router ID'],'Pakiet nie może dotrzeć do końca tunelu tylko przez tunel, który wymaga tej osiągalności. Cel musi mieć niezależną trasę underlay.')
C('Bezpieczna zależność routingu','Cel GRE to 198.51.100.2. Dodaj trasę hostową przez fizyczny next hop 192.0.2.254.','ip route 198.51.100.2 {{b0}} {{b1}}',['255.255.255.255','192.0.2.254'],'Trasa /32 do zewnętrznego celu przez underlay może zapobiec wyborowi drogi przez overlay. Next hop musi być osiągalny.')
Q('Up/up bez testu','Tunnel0 pokazuje up/up, keepalive nie skonfigurowano. Czy to dowodzi odbioru pakietów przez drugi koniec?', ['Nie, potrzebny jest test end-to-end','Tak, każde GRE ma wbudowany trójstronny handshake','Tak, up/up dowodzi poprawnego IPsec','Nie, bo GRE nigdy nie działa'],'Status lokalny bez keepalive nie potwierdza pełnej dwukierunkowej łączności. Sprawdź ping i routing obu końców.')
Q('MTU po enkapsulacji','Underlay MTU wynosi 1500, narzut dokładnie 24 B. Jaki maksymalny pakiet wewnętrzny zmieści się bez fragmentacji?', ['1476 B','1500 B','1524 B','1460 B'],'1500 − 24 = 1476 B. Wartość dotyczy całego wewnętrznego pakietu IP, nie samego payload TCP.')
Q('Duże pakiety zawodzą','Mały ping przez GRE działa, duży z DF nie. Najbardziej trafny kierunek diagnozy to:', ['MTU, PMTUD i blokowanie komunikatów ICMP','Zmiana BGP AS bez analizy','Usunięcie wszystkich tras connected','Wyłącznie zmiana hostname'],'Narzut tunelu zmniejsza dostępną wielkość pakietu. PMTUD wymaga prawidłowego dostarczania odpowiednich komunikatów ICMP.')
C('Kompletny koniec GRE','R1: source 192.0.2.1, destination 198.51.100.2, Tunnel0 10.255.0.1/30. Uzupełnij trzy wartości.','interface Tunnel0\n ip address {{b0}} 255.255.255.252\n tunnel source {{b1}}\n tunnel destination {{b2}}\n tunnel mode gre ip',['10.255.0.1','192.0.2.1','198.51.100.2'],'Konfiguracja rozdziela adres wewnętrzny i zewnętrzne końce. Zdalny router potrzebuje konfiguracji odwrotnej i routingu underlay.')
Q('TCP MSS','Załóż wewnętrzne MTU 1476 B oraz IPv4 i TCP bez opcji po 20 B. Jaki MSS mieści się w tym MTU?', ['1436 B','1476 B','1456 B','1500 B'],'MSS to dane TCP: 1476 − 20 − 20 = 1436 B. Nie utożsamiaj MSS z MTU.')
C('Zdalny koniec GRE','R2: outer source 198.51.100.2, destination R1 192.0.2.1, Tunnel0 10.255.0.2/30.','interface Tunnel0\n ip address {{b0}} 255.255.255.252\n tunnel source {{b1}}\n tunnel destination {{b2}}\n tunnel mode gre ip',['10.255.0.2','198.51.100.2','192.0.2.1'],'Oba końce mają zamienione zewnętrzne source/destination, ale różne adresy w tej samej podsieci overlay.')
Q('Tunel działa, LAN nie','Ping pomiędzy adresami Tunnel działa w obie strony, lecz hosty LAN nie komunikują się. Co sprawdzić dalej?', ['Trasy do LAN, trasy powrotne i polityki','Wyłącznie zamienić source z destination','Zawsze wyłączyć GRE','Wyłącznie numer protokołu OSPF'],'Osiągalność samego łącza Tunnel nie zapewnia znajomości sieci za jego końcami ani zgody polityk bezpieczeństwa.')
end()
EIGRP='https://www.cisco.com/c/en/us/support/docs/ip/enhanced-interior-gateway-routing-protocol-eigrp/16406-eigrp-toc.html'
start('routing-compare','EIGRP a OSPF — metryki i zbieżność','3.2.a',[EIGRP,OSPF])
Q('Rodzina protokołu','Jak sklasyfikować EIGRP w porównaniu z OSPF?', ['EIGRP: advanced distance vector; OSPF: link state','Oba: path vector','EIGRP: link state; OSPF: distance vector','Oba: protokoły warstwy 2'],'EIGRP wykorzystuje mechanizmy DUAL i informacje od sąsiadów. OSPF buduje bazę stanu łączy i oblicza SPF.')
Q('Algorytm OSPF','Który algorytm oblicza drzewo najkrótszych ścieżek OSPF?', ['Dijkstra SPF','DUAL','BGP best path','STP root election'],'OSPF oblicza SPF na podstawie LSDB. DUAL należy do EIGRP.')
Q('Algorytm EIGRP','Który mechanizm służy do wyboru bezpętlowych tras i zbieżności EIGRP?', ['DUAL','Dijkstra jako jedyny mechanizm EIGRP','CSMA/CD','LACP'],'DUAL dobiera successor i może zachować zapasową trasę spełniającą warunek wykonalności.')
Q('Domyślna metryka klasyczna','Jakie składniki mają domyślnie znaczenie dla klasycznej metryki EIGRP przy standardowych K-values?', ['Minimalna przepustowość i suma opóźnień','Wyłącznie liczba routerów','Wyłącznie adres router ID','MTU pomnożone przez numer AS'],'Domyślnie klasyczna metryka korzysta z bandwidth i delay. Load i reliability nie są domyślnie aktywne.')
Q('Koszt OSPF','Przy automatycznym koszcie interfejsu OSPF która zmiana może wpływać na koszt?', ['Zmiana bandwidth lub reference bandwidth','Zmiana lokalnego hasła użytkownika','Zmiana numeru VLAN bez zmiany łącza','Zmiana portu SSH'],'Koszt automatyczny opiera się na przepustowości odniesienia i przepustowości interfejsu. Można też ustawić koszt jawnie.')
Q('Hierarchia','Który protokół wykorzystuje backbone area 0 i ABR?', ['OSPF','EIGRP','Oba zawsze','Żaden'],'OSPF ma hierarchię obszarów. EIGRP nie organizuje topologii w obszary OSPF.')
Q('Successor','W terminologii EIGRP czym jest successor?', ['Wybrany next hop najlepszej trasy do celu','Zawsze router zapasowy','Zawsze DR segmentu','Host, który odpowiada na ARP'],'Successor zapewnia najlepszą trasę wybraną przez EIGRP. Feasible successor jest kandydatem zapasowym spełniającym warunek.')
Q('Reported distance','Sąsiad EIGRP zgłasza RD 900. Czego dotyczy ta wartość?', ['Kosztu od sąsiada do celu','Kosztu lokalnego łącza do sąsiada','Liczby odebranych pakietów','Administracyjnej odległości OSPF'],'Reported distance opisuje metrykę, którą sąsiad zgłasza dla swojej drogi do sieci docelowej.')
Q('Warunek wykonalności','Lokalne FD wynosi 2000. Kandydat zgłasza RD 1500. Czy spełnia warunek wykonalności?', ['Tak, RD jest mniejsze od FD','Nie, RD musi być większe','Tylko gdy RD jest równe FD','Nie, bo FD musi wynosić 90'],'Warunek to ścisła nierówność RD < FD. Nie oznacza ona automatycznie instalacji do load balancing.')
Q('Równość nie wystarczy','FD wynosi 2000, a RD zapasowego sąsiada również 2000. Czy spełniono feasibility condition?', ['Nie','Tak','Tylko dla IPv4','Tylko w area 0'],'RD musi być mniejsze od FD, a nie mniejsze lub równe. To warunek bezpętlowości zapasowej ścieżki.')
Q('Nierówne koszty','Który mechanizm jest charakterystyczny dla równoważenia EIGRP po ścieżkach o nierównych metrykach?', ['Variance z zachowaniem warunków dopuszczenia ścieżki','OSPF area range','BGP router-id','STP portfast'],'EIGRP może użyć variance do nierównych kosztów. Ścieżki nadal muszą spełniać warunki DUAL; variance nie wyłącza ochrony przed pętlami.')
Q('Wybór protokołu w RIB','Dla identycznego /24 istnieją poprawne trasy internal EIGRP i OSPF, domyślne AD. Która jest preferowana?', ['Internal EIGRP: AD 90','OSPF: AD 110','Zawsze większa metryka numeryczna','Obie, bo metryki są nieporównywalne'],'Dla tego samego prefiksu domyślne AD internal EIGRP 90 jest niższe od OSPF 110. Metryki różnych protokołów nie są porównywane bezpośrednio.')
Q('Feasible successor a awaria','Successor znika, a istnieje feasible successor. Jaka jest korzyść?', ['Możliwa szybka zmiana na znaną bezpętlową drogę','Wymóg restartu wszystkich routerów','Automatyczne przejście na OSPF','Konieczność zmiany AS'],'DUAL może wykorzystać wcześniej znaną zapasową ścieżkę spełniającą warunek, bez pełnego poszukiwania przez zapytania.')
Q('Brak feasible successor','Trasa EIGRP traci successor i nie ma feasible successor. Jakie zachowanie może nastąpić?', ['Przejście trasy w Active i wysłanie zapytań','Wybranie dowolnego sąsiada bez kontroli pętli','Natychmiastowy wybór DR','Obowiązkowe wyłączenie całego procesu'],'Active dotyczy obliczania konkretnej trasy przez DUAL. Nie należy mylić tego stanu ze stanem sesji BGP Active.')
Q('Variance z ograniczeniem','FD najlepszej trasy to 1000, variance 2. Kandydat ma całkowitą metrykę 1800, ale RD 1200. Dlaczego nie wystarczy limit variance?', ['RD 1200 nie spełnia RD < FD 1000','1800 jest większe od 2000','Variance dotyczy tylko OSPF','Kandydat musi mieć identyczny router ID'],'Sama metryka mieszcząca się w mnożniku nie wystarcza. Kandydat musi też spełnić feasibility condition.')
Q('Koszty OSPF na dwóch drogach','Droga A ma koszty interfejsów 10 + 20, a B 5 + 40. Pozostałe warunki wyboru są takie same. Co wybierze OSPF?', ['A, koszt 30','B, koszt 45','B, bo pierwszy link ma koszt 5','Zawsze drogę z większą przepustowością ostatniego linku'],'OSPF sumuje koszty wzdłuż ścieżki. Najniższy koszt pojedynczego pierwszego łącza nie przesądza wyboru.')
Q('External EIGRP kontra OSPF','Ten sam /24 ma trasę external EIGRP z AD 170 i OSPF z AD 110. Która wygra w RIB przy tych AD?', ['OSPF','External EIGRP','Trasa z dłuższą nazwą protokołu','Nie można wybrać żadnej'],'Niższa odległość administracyjna wygrywa dla tego samego prefiksu. External EIGRP ma inne domyślne AD niż internal EIGRP.')
Q('Najdłuższy prefiks','RIB zawiera OSPF 10.1.0.0/16 i EIGRP 10.1.2.0/24. Pakiet jest do 10.1.2.9. Co rozstrzyga lookup?', ['Najdłuższy prefiks: /24','Wyłącznie porównanie AD obu wpisów','Wyłącznie koszt OSPF','Losowanie protokołu'],'Forwarding wybiera najbardziej szczegółową pasującą trasę. AD służy do wyboru źródła dla tego samego prefiksu.')
end()
QOS='https://www.cisco.com/c/en/us/support/docs/quality-of-service-qos/qos-packet-marking/10103-dscpvalues.html'
QCFG='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/qos/b-quality-of-service/m_qos-mrkg.html'
start('qos-interpret','QoS — czytanie konfiguracji i liczników','1.4',[QOS,QCFG])
Q('Klasyfikacja','Co robi match ip dscp ef w class-map?', ['Dopasowuje pakiety oznaczone EF','Szyfruje pakiety EF','Zmienia MTU na 46','Automatycznie ustawia DSCP każdego pakietu'],'Match klasyfikuje istniejące oznaczenie. Samo dopasowanie nie jest znakowaniem ani kolejką priorytetową.')
Q('DSCP EF','Jaką wartość dziesiętną ma DSCP Expedited Forwarding?', ['46','5','0','63'],'EF ma DSCP 46. Wartość IP precedence 5 nie jest tym samym sześciobitowym polem.')
Q('Klasa domyślna','W policy-map istnieją VOICE i class-default. Który ruch trafia do class-default?', ['Ruch nieprzypisany do wcześniejszych klas polityki','Wyłącznie pakiety VLAN 1','Tylko ARP','Wszystkie pakiety niezależnie od wcześniejszego dopasowania'],'Class-default obejmuje pozostały ruch. Nie oznacza konkretnego VLAN-u ani automatycznie ruchu głosowego.')
Q('Kierunek polityki','Na Gi0/0 jest service-policy output WAN. Który ruch podlega tej polityce?', ['Wysyłany przez Gi0/0','Odbierany przez Gi0/0','Tylko lokalne logi','Wyłącznie sesje SSH do routera'],'Output odnosi się do kierunku wyjściowego tego interfejsu. Input klasyfikuje kierunek wejściowy.')
Q('Marking','W klasie policy-map skonfigurowano set dscp af31. Jaki jest bezpośredni efekt?', ['Ustawienie znacznika DSCP pasujących pakietów','Zagwarantowanie 31 Mb/s','Utworzenie 31 kolejek sprzętowych','Szyfrowanie ruchu klasy'],'Set oznacza pakiety, ale samo znakowanie nie zapewnia pasma ani priorytetu w dalszej sieci.')
Q('Ograniczenie QoS','Czy konfiguracja QoS może stworzyć dodatkową fizyczną przepustowość przeciążonego łącza?', ['Nie, zarządza wykorzystaniem istniejących zasobów','Tak, przez DSCP 63','Tak, przez zmianę nazwy policy-map','Tak, każdy class-map podwaja pasmo'],'QoS zarządza obsługą ruchu i stratami. Nie zwiększa przepustowości medium.')
Q('LLQ','W polityce wyjściowej klasa VOICE ma priority percent 10. Jaki jest cel tego polecenia?', ['Obsługa z małym opóźnieniem przez kolejkę priorytetową z limitem','Przydzielenie dziesięciu adresów IP','Zmiana wszystkich DSCP na 10','Wyłączenie innych klas bez ograniczeń'],'Priority tworzy obsługę priorytetową; limit chroni pozostały ruch podczas przeciążenia. Szczegóły zależą od platformy.')
Q('Bandwidth','Klasa DATA ma bandwidth percent 30 w klasycznym CBWFQ. Co oznacza ta rezerwacja?', ['Minimalny udział pasma podczas przeciążenia','Bezwzględny limit 30% w każdych warunkach','Wymóg DSCP 30','Trzydzieści pakietów na sekundę'],'Bandwidth określa gwarancję podczas konkurencji. Przy wolnych zasobach klasa może korzystać z większego pasma.')
Q('Policing','Policer ma conform-action transmit oraz exceed-action drop. Co stanie się z ruchem exceed?', ['Zostanie odrzucony','Zawsze poczeka w buforze shapera','Dostanie automatycznie EF','Zostanie skopiowany do SPAN'],'W tym przykładzie excess jest odrzucany. Policing może stosować różne akcje, lecz nie oznacza domyślnie wygładzania kolejką.')
Q('Shaping','Czym shaping różni się od policera odrzucającego nadmiar?', ['Może buforować i opóźniać nadmiar, by wygładzić wysyłanie','Zawsze szyfruje nadmiar','Nie wpływa na opóźnienie','Zawsze usuwa całą kolejkę'],'Shaping dopasowuje tempo z użyciem buforowania. To może zwiększać opóźnienie, ale ograniczać gwałtowne odrzucenia.')
Q('Match-any','Class-map match-any ma match dscp af31 i match dscp af32. Jaka relacja łączy kryteria?', ['Logiczne OR','Logiczne AND','Oba znaczniki muszą wystąpić jednocześnie','Drugie polecenie zawsze kasuje pierwsze'],'Match-any wymaga spełnienia co najmniej jednego kryterium. Match-all wymaga wszystkich kryteriów.')
Q('Granica zaufania','Telefon oznacza głos EF, ale niezaufany laptop może oznaczyć dowolne dane EF. Co powinien rozstrzygać projekt QoS?', ['Gdzie oznaczenia są zaufane, a gdzie weryfikowane lub zmieniane','Czy wszystkie pakiety EF są kryptograficznie podpisane','Czy EF wyłącza ACL','Czy DSCP zastępuje uwierzytelnienie'],'Znacznik nie jest dowodem tożsamości. Granica zaufania zapobiega nadużyciu preferencyjnej klasy.')
Q('Licznik klasy jest zerowy','show policy-map interface pokazuje zero trafień VOICE. Telefon wysyła DSCP 0, a klasa dopasowuje tylko EF. Najbardziej bezpośrednia przyczyna?', ['Ruch nie spełnia kryterium klasy','Zbyt krótka nazwa VOICE','OSPF area 0 blokuje QoS','Każdy pakiet automatycznie przechodzi do LLQ'],'Klasyfikacja zależy od faktycznego DSCP na punkcie zastosowania polityki. Sprawdź znakowanie oraz kierunek.')
Q('Polityka istnieje, ale nie działa','Running-config ma class-map i policy-map, lecz żaden interfejs nie ma service-policy. Jaki wniosek?', ['Zdefiniowana polityka nie jest jeszcze zastosowana na interfejsie','Polityka automatycznie działa wszędzie','Nazwa policy-map aktywuje ją globalnie','Wystarczy zapisać startup-config'],'Definicja polityki jest oddzielna od jej zastosowania. Potrzebne jest powiązanie z odpowiednim punktem i kierunkiem.')
Q('Obliczenie udziału','Dla zadania efektywna podstawa bandwidth percent wynosi 20 Mb/s. Klasa ma bandwidth percent 25. Ile wynosi jej rezerwacja?', ['5 Mb/s','25 Mb/s','0,8 Mb/s','20 Mb/s'],'25% z 20 Mb/s to 5 Mb/s. To obliczenie rezerwacji przy podanej podstawie, a nie zawsze twardy limit.')
Q('Dwa narzędzia razem','Parent policy kształtuje łącze do 10 Mb/s, a child policy ma LLQ i klasy CBWFQ. Jaki jest cel połączenia?', ['Dopasowanie tempa do usługi i podział obsługi między klasy','Dwukrotne szyfrowanie pakietów','Usunięcie wszystkich kolejek','Zastąpienie routingu przez DSCP'],'Hierarchiczna polityka może najpierw ograniczyć tempo do usługi operatora, a następnie rozdzielać zasoby między klasy.')
Q('Drop precedence AF','W tej samej klasie AF3 porównaj AF31 i AF33. Które oznaczenie wskazuje większą drop precedence?', ['AF33','AF31','Oba zawsze oznaczają strict priority','Numer klasy nie ma żadnego znaczenia'],'W AFxy druga cyfra oznacza drop precedence. AF33 ma większą skłonność do odrzucenia niż AF31 w odpowiedniej polityce.')
Q('Nie utożsamiaj oznaczenia z obsługą','Pakiet EF przechodzi przez router bez polityki obsługi EF. Co można stwierdzić?', ['Sam znacznik nie gwarantuje niskiego opóźnienia','EF zawsze wymusza sprzętową LLQ na każdym urządzeniu','EF rezerwuje pasmo end-to-end','EF omija każdy policer'],'Do realizacji QoS potrzebna jest spójna polityka na kolejnych węzłach. Oznaczenie opisuje żądaną klasę, nie wymusza samo gwarancji.')
end()
VIRT='https://developer.cisco.com/docs/sonic/vxlan-evpn/'
LISP='https://www.cisco.com/c/en/us/td/docs/routers/ios/config/17-x/ip-routing/b-ip-routing/m_irl-overview.html'
start('virtualization','Wirtualizacja — VM, LISP i VXLAN','2.1',[BP,VIRT,LISP])
Q('Hypervisor typu 1','Gdzie działa hypervisor typu 1?', ['Bezpośrednio na sprzęcie hosta','Wyłącznie wewnątrz przeglądarki','Zawsze jako aplikacja na desktopowym OS','W polu nagłówka Ethernet'],'Typ 1 zarządza sprzętem bez warstwy hostującego systemu operacyjnego typowej dla typu 2.')
Q('Hypervisor typu 2','Laborant uruchamia VM w aplikacji na swoim systemie desktopowym. Jaki typ hypervisora opisuje ten model?', ['Typ 2','Typ 1 z definicji','VTEP','ABR'],'Typ 2 działa nad systemem hosta. To rozróżnienie architektury, a nie liczby maszyn wirtualnych.')
Q('Interfejs VM','Jaką rolę pełni vNIC w maszynie wirtualnej?', ['Wirtualnego interfejsu sieciowego gościa','Tablicy routingu BGP','Fizycznego zasilacza','Wyłącznie kopii zapasowej VM'],'vNIC łączy system gościa z wirtualną siecią. Może być przyłączony do portu wirtualnego switcha.')
Q('Wirtualny switch','Dwie VM na jednym hoście są w tym samym segmencie vSwitch. Co może odbywać się lokalnie?', ['Przełączanie ruchu między VM bez wyjścia na fizyczny uplink','Każdy pakiet musi przejść przez Internet','Każdy pakiet wymaga MPLS','Żaden ruch, bo vSwitch nie ma tablicy MAC'],'Wirtualny switch może realizować lokalne przełączanie pomiędzy portami gości, zależnie od polityki i projektu.')
Q('Uplink hosta','Do czego służy fizyczny uplink vSwitcha?', ['Do połączenia wirtualnej sieci z siecią zewnętrzną','Wyłącznie do nadania RAM maszynie','Do tworzenia OSPF area 0 w każdym gościu','Do automatycznego szyfrowania dysków'],'Uplink zapewnia drogę między światem wirtualnym i fizyczną siecią. Segmenty i VLAN-y muszą być spójne.')
Q('Izolacja VM','Czy umieszczenie dwóch VM na jednym hoście oznacza automatycznie ten sam segment L2?', ['Nie, mogą należeć do różnych segmentów i polityk','Tak, zawsze','Tak, jeśli mają różne adresy MAC','Nie, bo VM nie obsługuje Ethernet'],'Rozdział może wynikać z VLAN-ów, port groups, wirtualnych switchy i polityk. Wspólny sprzęt nie narzuca wspólnego L2.')
Q('Cel VXLAN','Co przede wszystkim umożliwia VXLAN w overlay?', ['Przenoszenie segmentów L2 przez sieć L3','Zastąpienie każdego protokołu routingu','Szyfrowanie AES z definicji','Wyłącznie tunelowanie pojedynczego hosta bez MAC'],'VXLAN enkapsuluje ramki w transport IP/UDP, pozwalając tworzyć logiczne segmenty ponad underlay L3.')
Q('VTEP','Który element wykonuje enkapsulację i dekapsulację VXLAN?', ['VTEP','ABR OSPF','Serwer DNS jako obowiązkowa rola','DR BGP'],'VXLAN Tunnel Endpoint jest końcem tunelu. Może być realizowany sprzętowo lub programowo.')
Q('Identyfikator segmentu','Jaką szerokość ma pole VNI w VXLAN?', ['24 bity','12 bitów','6 bitów','128 bitów'],'24-bitowy VNI daje większą przestrzeń identyfikatorów niż 12-bitowy identyfikator VLAN.')
Q('Underlay VXLAN','Co musi zapewniać underlay między VTEP-ami?', ['Osiągalność IP i odpowiednią MTU dla enkapsulacji','Identyczny lokalny numer portu dostępowego','Wspólny process ID OSPF','Identyczne adresy MAC wszystkich hostów'],'Overlay wymaga transportu między końcami. Za małe MTU lub brak routingu może uszkodzić komunikację mimo poprawnych VNI.')
Q('EID w LISP','Co identyfikuje EID w modelu LISP?', ['Endpoint, oddzielony logicznie od lokalizacji routingu','Zawsze fizyczny port switcha','Numer VLAN transportowego','Hasło do tunelu'],'LISP rozdziela identyfikator endpointu EID i lokalizator routingu RLOC, by oddzielić tożsamość od położenia.')
Q('RLOC w LISP','Co opisuje RLOC?', ['Lokalizację routowalną używaną do transportu do końca tunelu','Tylko nazwę użytkownika','Maskę wildcard każdego EID','Rozmiar tablicy ARP'],'RLOC umożliwia dotarcie przez underlay do odpowiedniego węzła. System mapowania wiąże EID z RLOC.')
Q('BUM w VXLAN','Co oznacza BUM traffic w kontekście fabric?', ['Broadcast, unknown unicast, multicast','BGP, UDP, MPLS','Backup, update, monitoring','Best unicast metric'],'BUM wymaga mechanizmu dystrybucji do właściwych odbiorców overlay, np. replikacji ingress lub multicast zgodnie z projektem.')
Q('VNI to nie szyfrowanie','Dwa tenanty używają różnych VNI. Czy sam VXLAN zapewnia poufność przenoszonych danych?', ['Nie, enkapsulacja nie jest szyfrowaniem','Tak, VNI jest kluczem AES','Tak, UDP zawsze szyfruje payload','Tak, jeśli VNI jest większy niż 4095'],'Rozdział segmentów i poufność to różne właściwości. Dla poufności potrzebne są dodatkowe mechanizmy.')
Q('Rola ITR','Pakiet do zdalnego EID wchodzi do domeny LISP. Jaką rolę pełni ITR?', ['Enkapsuluje ruch do RLOC po uzyskaniu mapowania','Wyłącznie usuwa nagłówek po stronie docelowej','Nadaje priorytet STP','Zastępuje każdy serwer DHCP'],'Ingress Tunnel Router wysyła pakiet w enkapsulacji do właściwego RLOC. ETR odbiera i dekapsuluje ruch.')
Q('Rola ETR','Na docelowym brzegu LISP dociera pakiet enkapsulowany do lokalnego RLOC. Co robi ETR?', ['Dekapsuluje i dostarcza ruch do EID','Zawsze odrzuca pakiet jako multicast','Zmienia każdy EID na VLAN 1','Uruchamia sesję eBGP zamiast dostarczenia'],'Egress Tunnel Router kończy tunel po stronie docelowej. ITR i ETR mogą być rolami tego samego urządzenia xTR.')
Q('Nie działa tylko między hostami','VM w tym samym segmencie komunikują się lokalnie na hoście, lecz nie przez drugi host. Co jest rozsądnym następnym sprawdzeniem?', ['Uplinki, dozwolone VLAN-y lub transport overlay między hostami','Wyłącznie zwiększenie pamięci RAM VM','Wyłącznie zmiana hasła systemu gościa','Usunięcie wszystkich vNIC'],'Lokalna komunikacja potwierdza tylko część ścieżki. Połączenie między hostami wymaga sprawnego transportu i spójnego segmentu.')
Q('Przeniesienie endpointu','Endpoint LISP zmienia lokalizację, zachowując EID. Co powinno odzwierciedlić nowe położenie?', ['Mapowanie EID do nowego RLOC','Wymuszenie nowego EID przy każdym ruchu','Zmiana wszystkich router ID OSPF','Zastąpienie IP przez adres MAC w całym underlay'],'Oddzielenie identyfikatora od lokalizatora pozwala aktualizować mapowanie położenia bez utożsamiania obu wartości.')
